contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint v1, uint v2) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (v1) + (v2)); require(v1 <= 1000000000000000000000000000000); require(v2 <= 1000000000000000000000000000000);
        require(address(this).balance >= v1 + v2);
        require(c.getBalance(address(this)) == 0);
        uint preSelf = address(this).balance;
        uint preC = address(c).balance;
        c.addToBalance{value: v1}(); if (__ESBMC_reverted()) return;
        c.addToBalance{value: v2}(); if (__ESBMC_reverted()) return;
        assert(
            c.getBalance(address(this)) == v1 + v2 &&
            address(c).balance == preC + v1 + v2 &&
            address(this).balance == preSelf - v1 - v2
        );
    }
    receive() external payable {}
}

