// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 v1, uint256 v2) internal {
        v1 = bound(v1, 0, 1000000000000000000000000000000);
        v2 = bound(v2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= v1 + v2);
        vm.assume(c.getBalance(address(this)) == 0);
        uint preSelf = address(this).balance;
        uint preC = address(c).balance;
        try c.addToBalance{value: v1}() {} catch { return; }
        try c.addToBalance{value: v2}() {} catch { return; }
        assertTrue(c.getBalance(address(this)) == v1 + v2 &&
            address(c).balance == preC + v1 + v2 &&
            address(this).balance == preSelf - v1 - v2);
    }

    function testFuzz_run(uint256 v1, uint256 v2) public {
        _run(v1, v2);
    }

    receive() external payable {}
}
